<?php

declare(strict_types=1);

namespace Architex\Tests\Integration\SupplierProcurement;

use Architex\Platform\Identity\Identifier;
use Architex\Platform\SupplierProcurement\SupplierCatalogueNormaliser;
use Architex\Platform\SupplierProcurement\SupplierProcurementException;
use Architex\Platform\SupplierProcurement\SupplierProcurementService;
use Architex\Tests\Support\MariaDbTestCase;

final class SupplierProcurementServiceTest extends MariaDbTestCase
{
    public function testApprovedBaselineToPaymentRecommendationIsTenantScopedAndHumanGoverned():void
    {
        [$o,$owner,$member,$viewer,$project]=$this->tenant('supplier-a');[$other,$otherOwner,,,$otherProject]=$this->tenant('supplier-b');$file=$this->file($o,$project,$owner,'catalogue.csv','text/csv');$invoiceFile=$this->file($o,$project,$owner,'invoice.pdf','application/pdf');$foreignFile=$this->file($other,$otherProject,$otherOwner,'foreign.csv','text/csv');
        $service=new SupplierProcurementService($this->pdo,new SupplierCatalogueNormaliser());
        $supplier=$service->registerSupplier($o,$owner,'owner',$project,['name'=>'Gauteng Materials','capabilityLevel'=>1,'serviceRegions'=>['Gauteng'],'contactEmail'=>'orders@example.test']);self::assertSame('catalogue_upload_ready',$supplier['connectorStatus']);
        $catalogue=$service->importCatalogue($o,$member,'member',$supplier['id'],['sourceKind'=>'csv_upload','sourceFileId'=>$file,'idempotencyKey'=>'catalogue-a-1','items'=>[['sku'=>'BR-01','name'=>'Clay face brick SANS 227','category'=>'masonry','unit'=>'each','priceZar'=>8.5,'stockQuantity'=>5000,'leadTimeDays'=>4,'standards'=>['SANS 227'],'deliveryRegions'=>['gauteng']]]]);self::assertSame(1,$catalogue['itemCount']);self::assertTrue($service->importCatalogue($o,$member,'member',$supplier['id'],['sourceKind'=>'csv_upload','sourceFileId'=>$file,'idempotencyKey'=>'catalogue-a-1','items'=>[['sku'=>'ignored']]])['idempotentReplay']);
        $this->expectReason(fn()=>$service->importCatalogue($o,$member,'member',$supplier['id'],['sourceKind'=>'csv_upload','sourceFileId'=>$foreignFile,'idempotencyKey'=>'foreign','items'=>[['sku'=>'X','name'=>'X','category'=>'x','unit'=>'each','priceZar'=>1,'stockQuantity'=>1,'leadTimeDays'=>1]]]),'supplier_file_not_found');
        $baseline=$service->createBaseline($o,$member,'member',$project,['title'=>'Approved masonry baseline','sourceFileIds'=>[$file],'lines'=>[['sourceItemRef'=>'BOM-001','description'=>'SANS compliant clay face brick','category'=>'masonry','requiredStandard'=>'SANS 227','quantity'=>1000.0,'unit'=>'each','allowSubstitution'=>false,'requiredOnSiteDate'=>'2026-10-15','sourceDocumentIds'=>[]]]]);
        $this->expectReason(fn()=>$service->buildPackage($o,$member,'member',$baseline['id'],['title'=>'Masonry supply','projectRegion'=>'gauteng']),'supplier_approved_baseline_required');
        $this->expectReason(fn()=>$service->approveBaseline($o,$owner,'owner',$baseline['id'],['expectedVersion'=>1,'humanConfirmed'=>false,'reason'=>'No']),'supplier_baseline_confirmation_required');
        $approved=$service->approveBaseline($o,$owner,'owner',$baseline['id'],['expectedVersion'=>1,'humanConfirmed'=>true,'reason'=>'Principal reviewed the exact BoM source and quantities.']);self::assertSame('approved',$approved['status']);self::assertMatchesRegularExpression('/^[a-f0-9]{64}$/',$approved['snapshotSha256']);
        $this->expectReason(fn()=>$service->approveBaseline($o,$owner,'owner',$baseline['id'],['expectedVersion'=>1,'humanConfirmed'=>true,'reason'=>'Stale']),'supplier_baseline_transition_invalid');
        $package=$service->buildPackage($o,$member,'member',$baseline['id'],['title'=>'Masonry supply','projectRegion'=>'gauteng']);self::assertSame('procurement_package_created',$package['status']);
        $matches=$service->matchCatalogue($o,$member,'member',$package['id']);self::assertNotEmpty($matches);self::assertTrue($matches[0]['advisoryOnly']);self::assertGreaterThanOrEqual(80,$matches[0]['score']);
        $this->expectReason(fn()=>$service->issueRfq($o,$member,'member',$package['id'],['supplierId'=>$supplier['id'],'expiresInDays'=>14,'humanConfirmed'=>false]),'supplier_rfq_confirmation_required');
        $revocable=$service->issueRfq($o,$member,'member',$package['id'],['supplierId'=>$supplier['id'],'expiresInDays'=>14,'humanConfirmed'=>true]);$revoked=$service->revokeRfq($o,$owner,'owner',$revocable['id'],['humanConfirmed'=>true,'reason'=>'Commercial invitation withdrawn by accountable owner.']);self::assertSame('revoked',$revoked['status']);$this->expectReason(fn()=>$service->viewRfq($revocable['accessToken']),'supplier_rfq_not_found');
        $rfq=$service->issueRfq($o,$member,'member',$package['id'],['supplierId'=>$supplier['id'],'expiresInDays'=>14,'humanConfirmed'=>true]);self::assertSame(43,strlen($rfq['accessToken']));
        $quote=$service->submitQuote($rfq['accessToken'],['quoteReference'=>'QT-100','validUntil'=>'2026-09-30','lines'=>[['packageLineId'=>$matches[0]['packageLineId'],'quantity'=>1000.0,'unitPriceZar'=>8.5,'stockQuantity'=>5000,'leadTimeDays'=>4,'standards'=>['SANS 227']]],'exclusions'=>[],'qualifications'=>[]]);self::assertSame(850000,$quote['totalCents']);
        self::assertSame('quote_comparison_ready',$service->workspace($o,$owner,'owner',$project)['packages'][0]['status']);
        $this->expectReason(fn()=>$service->approveAward($o,$owner,'owner',$package['id'],['selectedMatchIds'=>[$matches[0]['id']],'humanConfirmed'=>false,'reason'=>'No']),'supplier_award_confirmation_required');
        $award=$service->approveAward($o,$owner,'owner',$package['id'],['selectedMatchIds'=>[$matches[0]['id']],'humanConfirmed'=>true,'reason'=>'Client reviewed the compliant quote and programme risk.']);self::assertSame('approved',$award['decision']);
        $this->expectReason(fn()=>$service->issuePurchaseOrder($o,$owner,'owner',$package['id'],['orderNumber'=>'PO-001','humanConfirmed'=>false]),'supplier_purchase_order_confirmation_required');
        $po=$service->issuePurchaseOrder($o,$owner,'owner',$package['id'],['orderNumber'=>'PO-001','humanConfirmed'=>true]);self::assertSame(850000,$po['totalCents']);
        $this->expectReason(fn()=>$service->recordDelivery($o,$member,'member',$po['id'],['deliveryReference'=>'DN-PREMATURE','status'=>'delivered_to_site','evidenceFileIds'=>[],'idempotencyKey'=>'delivery-premature']),'supplier_purchase_order_acceptance_required');
        $acceptedOrder=$service->acceptPurchaseOrder($rfq['accessToken'],['humanConfirmed'=>true,'reason'=>'Supplier accepts the exact issued purchase order.']);self::assertSame('supplier_accepted',$acceptedOrder['status']);
        $delivery=$service->recordDelivery($o,$member,'member',$po['id'],['deliveryReference'=>'DN-001','status'=>'delivered_to_site','evidenceFileIds'=>[$file],'idempotencyKey'=>'delivery-a-1']);self::assertSame('delivered_to_site',$delivery['status']);
        $invoice=$service->captureInvoice($o,$member,'member',$po['id'],['invoiceNumber'=>'INV-001','amountZar'=>8500.0,'sourceFileId'=>$invoiceFile]);
        $blocked=$service->recommendPayment($o,$owner,'owner',$invoice['id'],['humanConfirmed'=>true,'reason'=>'Review delivery.','idempotencyKey'=>'payment-a-blocked']);self::assertSame('blocked',$blocked['decision']);self::assertSame('site_acceptance_required',$blocked['reason']);self::assertFalse($blocked['movesMoney']);
        $this->expectReason(fn()=>$service->recordSiteAcceptance($o,$member,'member',$delivery['id'],['decision'=>'accepted','reason'=>'No confirmation','humanConfirmed'=>false,'evidenceFileIds'=>[]]),'supplier_site_acceptance_confirmation_required');
        $accept=$service->recordSiteAcceptance($o,$member,'member',$delivery['id'],['decision'=>'accepted','reason'=>'Site manager checked quantity, condition and specification evidence.','humanConfirmed'=>true,'evidenceFileIds'=>[$file]]);self::assertSame('accepted',$accept['decision']);
        $payment=$service->recommendPayment($o,$owner,'owner',$invoice['id'],['humanConfirmed'=>true,'reason'=>'Accepted delivery and invoice reviewed for provider handoff.','idempotencyKey'=>'payment-a-ready']);self::assertSame('release_requested',$payment['decision']);self::assertSame('integration_required',$payment['providerStatus']);self::assertFalse($payment['movesMoney']);
        $workspace=$service->workspace($o,$viewer,'viewer',$project);self::assertCount(1,$workspace['suppliers']);self::assertCount(1,$workspace['packages']);self::assertSame('payment_review',$workspace['packages'][0]['status']);self::assertCount(1,$workspace['siteAcceptances']);self::assertCount(2,$workspace['paymentRecommendations']);self::assertFalse($workspace['boundaries']['aiMayApprove']);
        $this->expectReason(fn()=>$service->registerSupplier($o,$viewer,'viewer',$project,['name'=>'Forbidden','capabilityLevel'=>0,'serviceRegions'=>[]]),'supplier_permission_denied');
        $this->expectReason(fn()=>$service->workspace($other,$otherOwner,'owner',$project),'supplier_permission_denied');
        self::assertGreaterThanOrEqual(10,(int)$this->pdo->query("SELECT COUNT(*) FROM project_records WHERE organisation_id=UNHEX('$o') AND module_key='supplier_procurement'")->fetchColumn());
        self::assertGreaterThanOrEqual(10,(int)$this->pdo->query("SELECT COUNT(*) FROM audit_events WHERE organisation_id=UNHEX('$o') AND action LIKE 'supplier_procurement.%'")->fetchColumn());
    }

    private function expectReason(callable$callback,string$reason):void{try{$callback();self::fail('Expected '.$reason);}catch(SupplierProcurementException$e){self::assertSame($reason,$e->reason);}}
    /** @return array{string,string,string,string,string} */private function tenant(string$slug):array{$o=Identifier::generate();$owner=Identifier::generate();$member=Identifier::generate();$viewer=Identifier::generate();$this->pdo->prepare("INSERT INTO organisations(id,name,slug,status) VALUES(UNHEX(:id),:name,:slug,'active')")->execute(['id'=>$o,'name'=>$slug,'slug'=>$slug]);foreach([[$owner,'owner'],[$member,'member'],[$viewer,'viewer']]as$i=>[$u,$role]){$this->pdo->prepare("INSERT INTO users(id,email,password_hash,status,email_verified_at) VALUES(UNHEX(:id),:email,'hash','active',UTC_TIMESTAMP(6))")->execute(['id'=>$u,'email'=>$slug.$i.'@example.test']);$this->pdo->prepare("INSERT INTO organisation_memberships(id,organisation_id,user_id,role,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),:role,'active')")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u,'role'=>$role]);}$p=Identifier::generate();$this->pdo->prepare("INSERT INTO projects(id,organisation_id,project_code,project_name,client_name,municipality,property_reference,property_use,land_use_notes,lead_professional_role,created_by) VALUES(UNHEX(:id),UNHEX(:o),:code,:name,'Client','City','Erf 1','Office','','architect',UNHEX(:u))")->execute(['id'=>$p,'o'=>$o,'code'=>strtoupper(substr(hash('sha256',$slug),0,8)),'name'=>$slug,'u'=>$owner]);return[$o,$owner,$member,$viewer,$p];}
    private function file(string$o,string$p,string$u,string$name,string$mime):string{$id=Identifier::generate();$this->pdo->prepare("INSERT INTO stored_files(id,organisation_id,project_id,uploaded_by,original_name,storage_name,mime_type,byte_size,sha256) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:u),:name,:storage,:mime,4,:sha)")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'u'=>$u,'name'=>$name,'storage'=>substr(hash('sha256',$id),0,48),'mime'=>$mime,'sha'=>hash('sha256',$name)]);return$id;}
}
